def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def emit_rows():
    rows=[]
    def emit(event,**fields):rows.append(dict(event=event,**fields))
    return rows,emit

def test_actual_closure_and_both_frozen_copies():
    value=runtime.make_contract(project_root=R,source_root=runtime.S,suite="libero_goal",stage="components")
    watched=runtime.validate_contract(value,project_root=R,source_root=runtime.S)
    assert len(watched)==184
    inventory=json.loads((R/runtime.INVENTORY).read_text())
    assert len(inventory["files"])==173
    for rel,digest in inventory["files"].items():
        assert sha(R/rel)==sha(runtime.S/rel)==digest
    assert value["policy"]["expected_base_loads"]==1 and value["policy"]["scientific_settings_changed"] is False

