@pytest.mark.parametrize("bad",["shape","nan","metadata"])
def test_real_timing_keeps_bytes_and_other_scientific_checks(bad):
    original=profiling._validate_chunk
    values=np.arange(56,dtype=np.float64).reshape(8,7)+1.010742197890625
    before=values.tobytes()
    identity=dict(suite="libero_10",method="dense",visual_tokens=512)
    metadata=dict(schema="formal_main_v2",**identity,policy_calls=1,vision_calls=1,packing_calls=1,
        scorer_calls=0,future_head_calls=0,language_cache="disabled",diagnostic_indices_recorded=False)
    row=types.SimpleNamespace(environment_actions=values,metadata=metadata)
    events,emit=emit_rows()
    with pytest.raises(ValueError):original(row)
    with runtime.validator_scope(profiling,kind="timing",alias_module=formal_profiling,emit=emit):
        assert len(formal_profiling._validate_timed_chunk(row,identity))==64
        assert values.tobytes()==before
        altered=types.SimpleNamespace(environment_actions=values.copy(),metadata=copy.deepcopy(metadata))
        if bad=="shape":altered.environment_actions=values[:7]
        if bad=="nan":altered.environment_actions[0,0]=np.nan
        if bad=="metadata":altered.metadata["future_head_calls"]=1
        with pytest.raises(ValueError):formal_profiling._validate_timed_chunk(altered,identity)
    assert profiling._validate_chunk is formal_profiling._validate_chunk is original
    assert events[-1]["bindings_restored"] is True and values.tobytes()==before

def test_alias_tamper_exception_restores_exact_code():
    original=profiling._validate_chunk;code=original.__code__;events,emit=emit_rows()
    with pytest.raises(ValueError,match="scope/bindings"):
        with runtime.validator_scope(profiling,kind="timing",alias_module=formal_profiling,emit=emit):
            formal_profiling._validate_chunk=lambda chunk:None
            original.__code__=(lambda chunk:None).__code__
    assert original.__code__ is code and profiling._validate_chunk is formal_profiling._validate_chunk is original
    assert events[-1]["bindings_intact"] is False and events[-1]["bindings_restored"] is True

@pytest.fixture
def actual_lifecycle():
    assert not any(k=="prismatic" or k.startswith("prismatic.") for k in sys.modules)
    probe=runtime.load(R/runtime.PROBE,runtime.PROBE_SHA)
    cls,proof=runtime.derive_one_base_lifecycle(probe)
    assert proof["cardinality_edits"]=={"__init__":2,"load":1,"finish":1}
    life=cls(["/synthetic-model"],compat,runtime_path=runtime.S/runtime.RUNTIME,runtime_sha256=sha(runtime.S/runtime.RUNTIME))
    yield life
