@pytest.mark.parametrize("fault",["none","repeat","caught_failure"])
def test_actual_lifecycle_single_load_and_poison(actual_lifecycle,fault):
    module=types.SimpleNamespace();seen=[];events,emit=emit_rows()
    def loader(checkpoint,*,device,use_minimal_prismatic_compat):
        assert module.load_openvla_oft_components is loader
        seen.append(checkpoint)
        compat.install_prismatic_runtime_compat(use_minimal_compat=use_minimal_prismatic_compat)
        if fault=="caught_failure":raise RuntimeError("synthetic tensor load failure")
        return object()
    module.load_openvla_oft_components=loader
    def body():
        with runtime._one_base_loader_scope(module,actual_lifecycle,checkpoint="/synthetic-model",emit=emit):
            try:module.load_openvla_oft_components("/synthetic-model",device="synthetic-cpu",use_minimal_prismatic_compat=True)
            except RuntimeError:
                if fault!="caught_failure":raise
            if fault=="repeat":module.load_openvla_oft_components("/synthetic-model",device="synthetic-cpu",use_minimal_prismatic_compat=True)
    if fault=="none":body()
    else:
        with pytest.raises((RuntimeError,ValueError)):body()
    assert module.load_openvla_oft_components is loader and seen==["/synthetic-model"]
    assert events[-1]["original_binding_restored"] is True
    assert events[-1]["failed"] is (fault!="none")

@pytest.mark.parametrize("mutation",["missing","consumer_false","final_true"])
def test_actual_wrapper_rejects_unready_before_science(tmp_path,monkeypatch,mutation):
    wrapper=load(INT/"wrapper.py","independent_wrapper_"+mutation)
    p=tmp_path/"project"
    for rel,src in [(wrapper.WRAPPER_REL,INT/"wrapper.py"),(wrapper.CONTRACT_REL,INT/"contract.py")]:
        path=p/rel;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(src.read_bytes())
    ready=dict(schema="formal_main_v2",kind="formal_action_runtime_readiness",status="passed",reviewed_by="root",
        execution_version=contract.VERSION,scientific_settings_changed=False,final_evaluation_enabled=False,raw_consumer_ready=True)
    if mutation=="consumer_false":ready["raw_consumer_ready"]=False
    if mutation=="final_true":ready["final_evaluation_enabled"]=True
    rf=p/"results/formal_main_v2/ready.json";rf.parent.mkdir(parents=True,exist_ok=True);rf.write_text(json.dumps(ready))
    inv=dict(version=contract.VERSION,wrapper=wrapper.WRAPPER_REL,wrapper_sha256=sha(p/wrapper.WRAPPER_REL),
        support_files={wrapper.CONTRACT_REL:sha(p/wrapper.CONTRACT_REL)})
    if mutation!="missing":inv["runtime_readiness"]={"path":str(rf.relative_to(p)),"sha256":sha(rf)}
    original_load=wrapper.load;seen=[]
    def checked_load(path,name):
        seen.append(name)
        assert name=="action_exec_contract","unready request reached science"
        return original_load(path,name)
    monkeypatch.setattr(wrapper,"load",checked_load)
    with pytest.raises(ValueError):wrapper.verify(inv,project=p)
    assert seen==["action_exec_contract"]

def test_exact_two_resume_inputs_all_suites_no_mutable_config():
    for suite in runtime.SUITES:
        rel="results/formal_main_v2/"+suite+"/downstream/development/run"
        inv=dict(resume=True,stage="development",prior_review="results/formal_main_v2/previous.json",prior_job_ids=["1"],
            run_root=str(contract.P/rel),watched_files={},root_evidence_sha256={})
        for name in ["trials.jsonl","closed_loop_report.json","config.json","panel.json"]:
            inv["root_evidence_sha256"][rel+"/"+name]="1"*64
            inv["watched_files"][str(contract.P/rel/name)]="1"*64
        before=copy.deepcopy(inv)
        assert set(contract.resume_prefix_inputs(inv))=={str(contract.P/rel/name) for name in ["trials.jsonl","closed_loop_report.json"]}
        assert set(contract.immutable_watches(inv))=={str(contract.P/rel/name) for name in ["config.json","panel.json"]}
        assert inv==before
        inv["watched_files"][str(contract.P/rel/"trials.jsonl")]="2"*64
        with pytest.raises(ValueError):contract.resume_prefix_inputs(inv)

