@pytest.mark.parametrize("fault",[None,"runner","bad_runtime","mutate_watch","mutate_binding","identity_collision"])
def test_actual_entry_writer_and_fail_closed(entry_case,fault):
    b=entry_case;b.knobs["fault"]=fault;code=b.run()
    raw=(b.directory/"events.jsonl").read_bytes()
    rows=[json.loads(x) for x in raw.splitlines()]
    complete=json.loads((b.directory/"completion.json").read_text())
    assert raw.endswith(b"\n") and [x["seq"] for x in rows]==list(range(len(rows)))
    assert all(x["job_id"]=="123456" and x["invocation_sha256"]==sha(b.ip) for x in rows)
    assert complete["events_sha256"]==hashlib.sha256(raw).hexdigest()
    assert rows[-1]["event"]=="action_execution_end" and complete["scientific_completion_not_inferred"] is True
    assert b.legacy.run is b.original_run
    assert len(b.seen)==(0 if fault=="identity_collision" else 1)
    if fault is None:
        assert code==0 and complete["status"]=="returned" and complete["runtime_restored"] is True
        assert complete["runner_status"]=="synthetic_partial_science"
        assert b.seen[0][1]==dict(mode="evaluate",source_root=runtime.S,source_inventory=R/runtime.INVENTORY,adapter_sha256=runtime.LEGACY_SHA,resume=False)
        initial={p.name:p.read_bytes() for p in b.directory.iterdir()}
        with pytest.raises(FileExistsError):b.run()
        assert initial=={p.name:p.read_bytes() for p in b.directory.iterdir()}
    else:
        assert code==1 and complete["status"]=="failed" and complete["errors"]
        assert rows[-1]["exit_code"]==1

